                return t
                    .replace(/^Surfs*d+s*[:-]?s*/i, '')
                    .replace(/^Surfaces*d+s*[:-]?s*/i, '')
                    .replace(/^面s*d+s*[:-]?s*/i, '')
                    .trim();
