              const manufacturer = String(cd[1] ?? 'Unknown').trim() || 'Unknown';
              const price = Number.isFinite(cd[2]) ? Number(cd[2]) : null;
              if (!name) return;

              const now = Date.now();
              const key = manufacturer + '\\n' + name;
